try:
    import robot.api.logger as logging
except ImportError:
    import logging
from taf.internal.aliasing import aliasing_scope
from taf.hw.channel_emulator.channel_emulator import ChannelEmulator
from taf.hw.channel_emulator.factory import ChannelEmulatorFactory


class channel_emulator(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_emulators = aliasing_scope(name=__name__, lookup_arg='emulator',
                                                          lookup_type=ChannelEmulator)

    def __init__(self):
        self._factory = ChannelEmulatorFactory()
        self._device = None

    def setup(self, vendor, model=None, version=None, alias=None, **kwargs):
        """
        Connect to channel emulator via ssh and connect to telnet(optional) on port, and register alias.

        :param vendor: str, channel emulator vendor, e.g. Spirent
        :param model: str, optional, channel emulator model, e.g. VCE6
        :param version: str, optional, channel emulator, e.g. 0.1
        :param alias: str, optional, alias name
        :param kwargs: device specific parameters, e.g. 'Vertex', 'Propsim':
                       str host: channel emulator ip address
                       int port: channel emulator port
                       str proxy: optional, proxy ip address
                       str proxy_username: optional, proxy username
                       str proxy_password: optional, proxy password
                       int timeout: optional, timeout for channel emulator command, in seconds
        :return: channel emulator instance
        :exception: connection failed exception
        """
        self._device = self._factory.create(vendor, model, version, **kwargs)
        self._device.setup()
        self.configured_emulators.add(self._device, alias)
        return self._device

    @lookup_handler.implicit_lookup
    def teardown(self, emulator=None):
        """
        Disconnect the connection of channel emulator.

        :param emulator: optional, alias name
        :return:
        """
        emulator.teardown()

    @lookup_handler.implicit_lookup
    def load_local_system_setting_file(self, path, emulator=None):
        """
        Load local configuration file and transfer it to the channel emulator.

        :param path:  str, local configuration file path
        :param emulator: optional, alias name
        :return: str, RPI command response
        """
        return emulator.load_local_system_setting_file(path)

    @lookup_handler.implicit_lookup
    def load_remote_system_setting_file(self, path, emulator=None):
        """
        Load configuration file on remote pc

        :param path:  str, remote configuration file path
        :param emulator: optional, alias name
        :return: str, RPI command response
        """
        return emulator.load_remote_system_setting_file(path)

    @lookup_handler.implicit_lookup
    def query_fading_doppler_frequency(self, channel, path, emulator=None):
        """
        Query the fading doppler frequency.

        :param channel: int, channel number
        :param path: int, path
        :param emulator: optional, alias name
        :return: str, doppler frequency
        """
        return emulator.query_fading_doppler_frequency(channel, path)

    @lookup_handler.implicit_lookup
    def set_fading_doppler_frequency(self, channel, path, frequency, emulator=None):
        """
        Set the fading doppler frequency.

        :param channel: int, channel number
        :param path: int, path
        :param frequency:  float, doppler frequency
        :param emulator: optional, alias name
        :return: str, RPI command response
        """
        return emulator.set_fading_doppler_frequency(channel, path, frequency)

